'use strict';
const LIGHTNING_TRANSFERS=5,LIGHTNING_JUMP_RANGE=230,LIGHTNING_SPEED=760;
let lightningTransfers=[],lightningDischarges=[];
function fanaticSaint(u){if(u.type!==19||u.saintId==null||u.saintFallen)return null;return units.find(v=>v.id===u.saintId&&v.id!==u.id&&v.faction===u.faction&&v.hp>0)??null;}
function setupBattleSaints(){
 for(const u of units){if(u.type!==19)continue;const saint=alive().filter(v=>v.id!==u.id&&v.faction===u.faction).sort((a,b)=>dist(u,a)-dist(u,b)||a.id-b.id)[0];u.saintId=saint?.id??null;u.saintFallen=false;u.tags=[...TYPES[u.type].tags];if(!saint){u.tags=u.tags.filter(t=>t!=='의존형');u.tags.push('돌격형');}else fx('faithPrayer',u.x,u.y,u.color,.6,{tx:saint.x,ty:saint.y,saintId:saint.id});}
}
function updateFanaticFaith(){for(const u of alive()){if(u.type!==19||u.saintId==null||u.saintFallen||fanaticSaint(u)||units.some(v=>v.id===u.saintId&&v.hp>0))continue;u.saintFallen=true;u.tags=u.tags.filter(t=>t!=='의존형');if(!u.tags.includes('돌격형'))u.tags.push('돌격형');u.ai.disengageUntil=u.ai.returnUntil=0;u.ai.commitUntil=elapsed+2.5;u.ai.mode='approach';u.ai.attackDecision={targetId:u.targetId,at:elapsed+random(.1,.35),reason:'faith'};u.ai.nextInitiativeAt=elapsed+random(.4,1.3);u.action='성자 사망 · 광분';fx('faithRage',u.x,u.y,'#f29aaf',.65,{unitId:u.id,r:90});}}
function faithAttackFactor(u){const devotion=alive().filter(v=>v.type===19&&v.saintId===u.id&&v.faction===u.faction&&!v.saintFallen).length;return (1+devotion*.1)*(u.type===19&&u.saintFallen?1.3:1);}
function moveFanatic(u,target,enemies,allies,dt){
 const saint=fanaticSaint(u);if(!saint){if(!target){moveGeneral(u,target,enemies,allies,dt);return;}const d=dist(u,target)||1,dx=(target.x-u.x)/d,dy=(target.y-u.y)/d,radial=d>58?1.2:d<40?-.3:.15,side=u.ai.side;steerArchetype(u,dx*radial-dy*side*.18,dy*radial+dx*side*.18,dt,movementRate(u)*(u.attack?.phase==='windup'?.35:u.attack?.phase==='active'?.6:1.12));u.action=u.attack?u.attack.phase==='windup'?'단검 · 준비':'단검 공격':u.saintFallen?'광분 · 적 추격':'돌격 · 성자 없음';return;}
 const angle=target?Math.atan2(target.y-saint.y,target.x-saint.x):saint.face,side=u.ai.side,anchor={x:clamp(saint.x-Math.cos(angle)*70-Math.sin(angle)*side*58,45,755),y:clamp(saint.y-Math.sin(angle)*70+Math.cos(angle)*side*58,45,755)},gap=dist(u,saint),a=dist(u,anchor)||1;let mx=(anchor.x-u.x)/a*Math.min(1,a/50),my=(anchor.y-u.y)/a*Math.min(1,a/50);
 if(target&&gap<120&&dist(saint,target)<170&&elapsed<u.ai.commitUntil){const d=dist(u,target)||1;mx=mx*.25+(target.x-u.x)/d*.8;my=my*.25+(target.y-u.y)/d*.8;}
 if(gap>145){mx=(saint.x-u.x)/(gap||1);my=(saint.y-u.y)/(gap||1);}
 steerArchetype(u,mx,my,dt,movementRate(u)*(u.attack?.phase==='windup'?.3:u.attack?.phase==='active'?.6:1));u.action=u.attack?u.attack.phase==='windup'?'단검 · 준비':'단검 공격':gap>145?'성자에게 합류':'성자 곁 · 근접 견제';
}
function releaseFaithPrayer(u,a){const saint=fanaticSaint(u);if(!saint||saint.id!==a.targetId||!ULTIMATES[saint.type]||saint.ultCast)return false;const before=saint.ultGauge;gainUltimate(saint,20*combatFatigueFactor(saint,'charge'));if(saint.ultGauge===before)return false;fx('faithPrayer',u.x,u.y,'#ecd3ff',.65,{tx:saint.x,ty:saint.y,saintId:saint.id});burst(saint.x,saint.y,'#ddc4ff',14,100,.7,-Math.PI/2,'mote');return true;}
function resetLightningChains(){lightningTransfers=[];}
function resetLightningDischarges(){lightningDischarges=[];}
function launchChainLightning(u,a){const chain={remaining:LIGHTNING_TRANSFERS,recent:[],history:[],hits:0};const origin={x:u.x+Math.cos(a.angle)*38*unitScale(u),y:u.y+Math.sin(a.angle)*38*unitScale(u)};return createLightningBolt(u,origin,a.angle,u.dmg,chain,a.hiddenLaunch);}
function createLightningBolt(source,origin,angle,damage,chain,hiddenLaunch=false){const scale=unitScale(source),p={kind:'lightning',source,type:20,color:'#8ed9ff',x:origin.x,y:origin.y,vx:Math.cos(angle)*LIGHTNING_SPEED,vy:Math.sin(angle)*LIGHTNING_SPEED,damage,power:damage,life:1.15,radius:24*scale,visualScale:scale,impulse:140,trail:[],bouncesRemaining:0,homing:false,guaranteed:false,hiddenLaunch,chain,origin:{...origin},lightningSeed:visualRandom(0,100)};projectiles.push(p);source.shotsFired++;fx('gunFlash',origin.x,origin.y,'#bcecff',.12,{angle,r:42});return p;}
function chainLightningImpact(p,target){
 if(p.life<=0||p.chain.recent.includes(target.id))return;p.life=0;const origin={x:p.x-p.vx*.04,y:p.y-p.vy*.04},angle=Math.atan2(p.vy,p.vx),result=attackHit(target,p.damage,p.source,{angle,impulse:p.impulse,attackOrigin:origin,hiddenLaunch:p.hiddenLaunch,attackToken:p});fx('lightningLink',p.origin.x,p.origin.y,'#c3eeff',.18,{tx:p.x,ty:p.y,seed:p.lightningSeed});
 if(!(result.damage>0||result.absorbed>0))return;const chain=p.chain;chain.hits++;chain.history.push(target.id);chain.recent=[...chain.recent,target.id].slice(-2);
 if(chain.remaining>0)lightningTransfers.push({source:p.source,point:{x:target.x,y:target.y},chain,damage:p.damage*.9,hiddenLaunch:p.hiddenLaunch,wait:.08});
}
function advanceLightningTransfers(dt){const ready=[];for(const transfer of lightningTransfers){transfer.wait-=dt;if(transfer.wait<=1e-8)ready.push(transfer);}lightningTransfers=lightningTransfers.filter(t=>t.wait>1e-8);
 for(const t of ready){if(t.chain.remaining<=0)continue;const candidates=alive().filter(v=>v.faction!==t.source.faction&&!t.chain.recent.includes(v.id)&&canPerceive(t.source,v)&&dist(v,t.point)<=LIGHTNING_JUMP_RANGE*unitScale(t.source)).sort((a,b)=>dist(a,t.point)-dist(b,t.point)||a.id-b.id),target=candidates[0];if(!target)continue;t.chain.remaining--;const angle=Math.atan2(target.y-t.point.y,target.x-t.point.x),origin={x:t.point.x+Math.cos(angle)*12,y:t.point.y+Math.sin(angle)*12};createLightningBolt(t.source,origin,angle,t.damage,t.chain,t.hiddenLaunch);}
}
function applyLightningShock(target,source,stacks=1){
 if(source?.type!==20||target.hp<=0||source.faction===target.faction||stacks<=0)return;target.shockStacks=(target.shockStacks??0)+stacks;if(target.shockStacks<4)return;target.shockStacks%=4;stunParryEnemy(target,2.5);fx('shockBurst',target.x,target.y,'#a2e5ff',.45,{unitId:target.id,r:105});burst(target.x,target.y,'#c8f0ff',22,320,.9,Math.PI/2,'shard');impactPause(1.7,Math.PI/2);
}
function releaseLightningDischarge(u,a){const radius=280*unitScale(u);lightningDischarges.push({source:u,x:u.x,y:u.y,r:radius,t:0,duration:.22,hitIds:new Set(),damage:u.dmg*2.6,token:{}});fx('lightningDischarge',u.x,u.y,'#a6e5ff',.55,{r:radius,angle:a.angle,seed:visualRandom(0,100)});impactPause(2.8,a.angle);}
function advanceLightningDischarges(dt){for(const wave of lightningDischarges){wave.t+=dt;const radius=wave.r*clamp(wave.t/wave.duration,0,1);for(const target of alive()){if(target.faction===wave.source.faction||wave.hitIds.has(target.id)||dist(wave,target)>radius+24*unitScale(target))continue;wave.hitIds.add(target.id);const angle=Math.atan2(target.y-wave.y,target.x-wave.x);attackHit(target,wave.damage,wave.source,{angle,impulse:320,attackOrigin:wave,visibleHazard:true,hiddenLaunch:false,attackToken:wave.token,shockStacks:2});}}lightningDischarges=lightningDischarges.filter(w=>w.t<w.duration);}
function renderLightningRibbon(from,to,seed=0,width=5,alpha=1){const length=dist(from,to);if(length<1)return;const dx=(to.x-from.x)/length,dy=(to.y-from.y)/length,n=Math.max(3,Math.min(16,Math.ceil(length/22))),points=[];for(let i=0;i<=n;i++){const t=i/n,offset=i===0||i===n?0:(vfxNoise(i,seed)-.5)*20;points.push({x:from.x+dx*length*t-dy*offset,y:from.y+dy*length*t+dx*offset});}ctx.save();const opacity=ctx.globalAlpha*alpha;ctx.lineJoin='miter';for(const[color,w,a]of[['#417fad',width*2,.35],['#83d5ff',width,1],['#efffff',Math.max(2,width*.35),1]]){ctx.strokeStyle=color;ctx.lineWidth=w;ctx.globalAlpha=opacity*a;ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();}ctx.restore();}
function renderChainLightning(p){const angle=Math.atan2(p.vy,p.vx);renderLightningRibbon(p.origin,p,p.lightningSeed,5*(p.visualScale??1),.85);bladeStreak(p.x,p.y,angle,35,13,'#e5fcff');pixelSprite(p.x,p.y,'#9edfff',1,'star',.9);}
function renderFanaticWeapon(u,a,p){ctx.translate(22,14);sword(48,7,u.saintFallen?'#ffc2c7':'#e9d7ff');ctx.fillStyle=u.saintFallen?'#af5369':'#8d70a5';ctx.fillRect(1,-4,12,8);}
function renderLightningWeapon(u,a,p){ctx.translate(24,12);ctx.fillStyle='#6585a1';ctx.fillRect(-8,11,35,5);ctx.rotate(-.6);ctx.fillStyle='#a8c9e1';ctx.fillRect(-12,-3,54,6);ctx.fillStyle='#f0f8ff';ctx.fillRect(28,-7,17,4);ctx.fillRect(33,-11,6,22);const charge=a?.phase==='windup'||u.ultCast;pixelSprite(41,0,'#8bdbff',charge?1+p:1,'star',charge?.8:.4);if(charge)renderLightningRibbon({x:27,y:-20},{x:52,y:15},u.phase+elapsed*5,3,.7);}
function renderFaithLightningStatus(u){if(u.type===19&&u.saintFallen){for(const side of [-1,1])bladeStreak(u.x+side*29,u.y-5,-Math.PI/2,26,5,'#db7394',.55);}if((u.shockStacks??0)>0){for(let i=0;i<u.shockStacks;i++){const angle=-Math.PI/2+(i-1)*.55,r=35*unitScale(u);pixelSprite(u.x+Math.cos(angle)*r,u.y+Math.sin(angle)*r,'#93dcff',.55,'ember',.85);}}const devotees=alive().filter(v=>v.type===19&&v.saintId===u.id&&!v.saintFallen&&v.faction===u.faction);if(devotees.length){bladeStreak(u.x-6,u.y-34,-Math.PI/2,12,6,'#eedaff',.7);bladeStreak(u.x-6,u.y-34,0,14,3,'#fff0ff',.8);}}
function renderFaithLightningEffect(e){const p=1-e.life/e.max,alpha=1-p;if(e.kind==='lightningLink'){renderLightningRibbon(e,{x:e.tx,y:e.ty},e.seed,5,alpha);return;}if(e.kind==='faithPrayer'){const saint=units.find(u=>u.id===e.saintId),point={x:saint?.x??e.tx,y:saint?.y??e.ty};pixelBeam(e.x,e.y,point.x,point.y,'#b997d5',5,alpha*.5);for(const side of [-1,1])bladeStreak(point.x+side*20,point.y-5-p*45,-Math.PI/2,30*(1-p),7,'#eed6ff',alpha);return;}const u=e.unitId?units.find(v=>v.id===e.unitId):null,point={x:u?.x??e.x,y:u?.y??e.y};if(e.kind==='faithRage'){for(const side of [-1,1])bladeStreak(point.x+side*26,point.y-15-p*45,-Math.PI/2,60*(1-p),12,'#f09cb5',alpha);return;}
 const radius=e.r*(e.kind==='lightningDischarge'?clamp(p/.4,0,1):.7+.3*p),branches=e.kind==='lightningDischarge'?8:5;for(let i=0;i<branches;i++){const angle=i*Math.PI*2/branches+(e.angle??0),from={x:point.x+Math.cos(angle)*radius*.12,y:point.y+Math.sin(angle)*radius*.12},to={x:point.x+Math.cos(angle)*radius,y:point.y+Math.sin(angle)*radius};renderLightningRibbon(from,to,(e.seed??i)+i*3,e.kind==='lightningDischarge'?7:5,alpha*.9);if(p<.55)pixelSprite(to.x,to.y,'#b6ecff',1,'star',alpha*.6);}if(p<.35)hitGlyph(point.x,point.y,Math.PI/4,e.kind==='lightningDischarge'?75:45,'#d3f5ff',p,alpha);
}

// Cracked mirror: ordinary swept projectiles, with no tracking or guaranteed hit.
const MIRROR_BOUNCE_MULTIPLIER=1.2;
function mirrorProjectile(u,angle,damage,reflected=false){const scale=unitScale(u),p={kind:reflected?'mirrorReflection':'mirrorLight',source:u,type:u.type,x:clamp(u.x+Math.cos(angle)*36*scale,20.001,779.999),y:clamp(u.y+Math.sin(angle)*36*scale,20.001,779.999),vx:Math.cos(angle)*620,vy:Math.sin(angle)*620,damage,power:damage,impulse:145,color:reflected?'#f4ffff':u.color,radius:18*scale,visualScale:scale,life:reflected?2.5:10,trail:[],bouncesRemaining:reflected?0:4,bounceCount:0,homing:false,guaranteed:false,hiddenLaunch:false};projectiles.push(p);return p;}
function launchMirrorLight(u,a){mirrorProjectile(u,a.angle,u.dmg);fx('mirrorFlash',u.x+Math.cos(a.angle)*32,u.y+Math.sin(a.angle)*32,u.color,.28,{angle:a.angle,r:55});u.kx-=Math.cos(a.angle)*40;u.ky-=Math.sin(a.angle)*40;}
function startMirrorReflection(u){u.mirrorReflectTime=3;fx('mirrorFlash',u.x,u.y,'#d9ffff',.45,{angle:u.face,r:115,unitId:u.id});burst(u.x,u.y,'#b4e5e8',20,200,Math.PI*2,0,'shard');}
function interceptMirrorAttack(u,source,power,options={}){if(u.type!==21||u.hp<=0||!(u.mirrorReflectTime>0))return null;if(source&&source.id!==u.id&&source.faction!==u.faction&&power>0){const angle=Math.atan2(source.y-u.y,source.x-u.x);mirrorProjectile(u,angle,power,true);fx('mirrorFlash',u.x,u.y,'#ecffff',.3,{angle,r:85});burst(u.x,u.y,'#b4e5e8',14,250,.8,angle,'shard');impactPause(1.1,angle);}return{damage:0,absorbed:0,defended:true,kind:'mirror'};}
function returnMirrorShards(u,source,damage,options={}){if(u.type!==21||options.mirrorShard||!(damage>0)||!source||source.hp<=0||source.faction===u.faction)return;const returned=Math.round(damage*.1);if(returned<=0)return;fx('mirrorFlash',u.x,u.y,u.color,.22,{angle:Math.atan2(source.y-u.y,source.x-u.x),r:55});hit(source,returned,u,{mirrorShard:true,mirrorRaw:true,impulse:0,attackOrigin:u});}
function renderMirrorWeapon(u,a,p){ctx.save();ctx.translate(32+(a?.phase==='windup'?-p*8:0),9);ctx.rotate(a?.phase==='windup'?-p*.65:.12);ctx.fillStyle='#527787';ctx.fillRect(-9,-22,18,38);ctx.fillStyle='#b4e5e8';ctx.fillRect(-6,-19,12,31);ctx.strokeStyle='#416774';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(0,-19);ctx.lineTo(-3,-5);ctx.lineTo(5,2);ctx.lineTo(0,12);ctx.stroke();ctx.fillStyle='#fff';ctx.fillRect(-4,-16,3,10);if(a?.phase==='windup'){pixelSprite(0,-3,'#d5ffff',1+p,'star',.4+.6*p);bladeStreak(0,-3,0,18+25*p,5,'#e8ffff',p*.8);}ctx.restore();}
function renderMirrorProjectile(p){const angle=Math.atan2(p.vy,p.vx),scale=p.visualScale??1,boost=1+(p.bounceCount??0)*.12;bladeStreak(p.x-Math.cos(angle)*18,p.y-Math.sin(angle)*18,angle,70*scale*boost,9*scale,p.color,.8);bladeStreak(p.x,p.y,angle,30*scale*boost,5*scale,'#fff');pixelSprite(p.x,p.y,p.color,scale,'star',.8);}
function renderMirrorFlash(e){const p=1-e.life/e.max,alpha=Math.pow(1-p,1.5),u=e.unitId?units.find(v=>v.id===e.unitId):null,x=u?.x??e.x,y=u?.y??e.y;hitGlyph(x,y,e.angle??0,e.r,e.color,p,alpha*.75);for(let i=0;i<5;i++){const angle=(e.angle??0)+i*2.39996,r=e.r*(.15+.55*p);bladeStreak(x+Math.cos(angle)*r,y+Math.sin(angle)*r,angle,20*(1-p),4,'#d3ffff',alpha*.7);}}
function renderMirrorGuard(u){const alpha=Math.min(1,u.mirrorReflectTime/.35),r=38*unitScale(u);for(let i=0;i<5;i++){const angle=i*Math.PI*2/5+elapsed*.7;ctx.save();ctx.translate(u.x+Math.cos(angle)*r,u.y+Math.sin(angle)*r);ctx.rotate(angle+.5);ctx.fillStyle='#b4e5e8';ctx.globalAlpha*=alpha*.65;ctx.fillRect(-3,-9,6,18);ctx.fillStyle='#fff';ctx.fillRect(-1,-7,2,10);ctx.restore();}}
